import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { getRooms, type Room } from "./roomsApi";
import { CustomError } from "../model/CustomError";

export function Rooms() {
    const navigate = useNavigate();
    const [rooms, setRooms] = useState<Room[]>([]);
    const [error, setError] = useState("");
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        let active = true;

        getRooms()
            .then((result) => {
                if (active) setRooms(result);
            })
            .catch((err: unknown) => {
                if (!active) return;

                if (err instanceof CustomError) {
                    setError(err.message);
                    if (err.httpStatus === 401) {
                        navigate("/login");
                    }
                } else {
                    setError("Impossible de charger les salons.");
                }
            })
            .finally(() => {
                if (active) setLoading(false);
            });

        return () => {
            active = false;
        };
    }, [navigate]);

    function logout() {
        sessionStorage.removeItem("token");
        navigate("/login");
    }

    return (
        <main className="container mt-4">
            <div className="d-flex justify-content-between align-items-center mb-4">
                <h1>Salons de discussion</h1>
                <div>
                    <button
                        className="btn btn-outline-primary me-2"
                        onClick={() => navigate("/users")}
                    >
                        Messages privés
                    </button>
                    <button
                        className="btn btn-outline-danger"
                        onClick={logout}
                    >
                        Déconnexion
                    </button>
                </div>
            </div>

            {loading && <p>Chargement des salons...</p>}

            {error && (
                <div className="alert alert-danger" role="alert">
                    {error}
                </div>
            )}

            {!loading && !error && rooms.length === 0 && (
                <p>Aucun salon disponible.</p>
            )}

            <div className="list-group">
                {rooms.map((room) => (
                    <button
                        key={room.room_id}
                        type="button"
                        className="list-group-item list-group-item-action"
                        onClick={() => navigate(`/rooms/${room.room_id}`)}
                    >
                        <strong>{room.name}</strong>
                        <br />
                        <small className="text-muted">
                            Créé le {room.created_on}
                        </small>
                    </button>
                ))}
            </div>
        </main>
    );
}

import { useCallback, useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { getRooms, type Room } from "./roomsApi";
import {
    getRoomMessages,
    sendRoomMessage,
    type RoomMessage,
} from "./roomMessagesApi";
import { CustomError } from "../model/CustomError";

export function RoomConversation() {
    const { roomId: rawRoomId } = useParams();
    const roomId = Number(rawRoomId);
    const navigate = useNavigate();

    const [room, setRoom] = useState<Room | null>(null);
    const [messages, setMessages] = useState<RoomMessage[]>([]);
    const [content, setContent] = useState("");
    const [loading, setLoading] = useState(true);
    const [sending, setSending] = useState(false);
    const [error, setError] = useState("");

    const loadMessages = useCallback(async () => {
        try {
            const result = await getRoomMessages(roomId);
            setMessages(result);
            setError("");
        } catch (err: unknown) {
            if (err instanceof CustomError) {
                setError(err.message);
                if (err.httpStatus === 401) navigate("/login");
            } else {
                setError("Impossible de charger les messages.");
            }
        } finally {
            setLoading(false);
        }
    }, [roomId, navigate]);

    useEffect(() => {
        if (!Number.isInteger(roomId) || roomId <= 0) {
            navigate("/rooms", { replace: true });
            return;
        }

        let active = true;

        getRooms()
            .then((rooms) => {
                if (!active) return;
                const found = rooms.find((item) => item.room_id === roomId);

                if (!found) {
                    navigate("/rooms", { replace: true });
                    return;
                }

                setRoom(found);
            })
            .catch((err: unknown) => {
                if (!active) return;
                if (err instanceof CustomError) {
                    setError(err.message);
                    if (err.httpStatus === 401) navigate("/login");
                } else {
                    setError("Impossible de charger le salon.");
                }
            });

        return () => {
            active = false;
        };
    }, [roomId, navigate]);

    useEffect(() => {
        if (!Number.isInteger(roomId) || roomId <= 0) return;

        void loadMessages();
        const intervalId = window.setInterval(() => {
            void loadMessages();
        }, 5000);

        return () => window.clearInterval(intervalId);
    }, [roomId, loadMessages]);

    async function handleSend(event: React.FormEvent<HTMLFormElement>) {
        event.preventDefault();

        const trimmedContent = content.trim();
        if (!trimmedContent || sending) return;

        setSending(true);
        setError("");

        try {
            await sendRoomMessage(roomId, trimmedContent);
            setContent("");
            await loadMessages();
        } catch (err: unknown) {
            if (err instanceof CustomError) {
                setError(err.message);
                if (err.httpStatus === 401) navigate("/login");
            } else {
                setError("Impossible d'envoyer le message.");
            }
        } finally {
            setSending(false);
        }
    }

    function logout() {
        sessionStorage.removeItem("token");
        navigate("/login");
    }

    return (
        <main className="container mt-4">
            <div className="d-flex justify-content-between align-items-center mb-3">
                <div>
                    <h1>{room?.name ?? "Salon de discussion"}</h1>
                    <p className="text-muted mb-0">
                        Messages du salon
                    </p>
                </div>

                <div className="d-flex gap-2 flex-wrap">
                    <button
                        className="btn btn-outline-secondary"
                        onClick={() => navigate("/rooms")}
                    >
                        Salons
                    </button>
                    <button
                        className="btn btn-outline-primary"
                        onClick={() => navigate("/users")}
                    >
                        Messages privés
                    </button>
                    <button
                        className="btn btn-outline-danger"
                        onClick={logout}
                    >
                        Déconnexion
                    </button>
                </div>
            </div>

            {error && (
                <div className="alert alert-danger" role="alert">
                    {error}
                </div>
            )}

            <section
                className="border rounded p-3 mb-3"
                aria-label="Messages du salon"
                style={{ minHeight: "300px", maxHeight: "55vh", overflowY: "auto" }}
            >
                {loading && <p>Chargement des messages...</p>}

                {!loading && messages.length === 0 && (
                    <p className="text-muted">
                        Aucun message pour le moment. Lancez la discussion !
                    </p>
                )}

                {messages.map((message) => (
                    <article
                        key={message.id}
                        className="border-bottom py-2"
                    >
                        <div className="d-flex justify-content-between gap-3">
                            <strong>{message.senderUsername}</strong>
                            <small className="text-muted">
                                {new Date(message.createdAt).toLocaleString()}
                            </small>
                        </div>
                        <p className="mb-1" style={{ whiteSpace: "pre-wrap" }}>
                            {message.content}
                        </p>
                    </article>
                ))}
            </section>

            <form onSubmit={handleSend}>
                <label htmlFor="room-message" className="form-label">
                    Votre message
                </label>
                <div className="input-group">
                    <input
                        id="room-message"
                        className="form-control"
                        type="text"
                        maxLength={5000}
                        value={content}
                        onChange={(event) => setContent(event.target.value)}
                        placeholder="Écrire un message..."
                        disabled={sending}
                    />
                    <button
                        className="btn btn-primary"
                        type="submit"
                        disabled={sending || !content.trim()}
                    >
                        {sending ? "Envoi..." : "Envoyer"}
                    </button>
                </div>
            </form>
        </main>
    );
}

