import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { getUsers, type PublicUser } from "./usersApi";
import { CustomError } from "../model/CustomError";
import { useMessagingStore } from "../store/messagingStore";
import { initializeBeams } from "./beams";

export function Users() {
    const [error, setError] = useState("");
    const [loading, setLoading] = useState(true);
    const navigate = useNavigate();

    const users = useMessagingStore((state) => state.users);
    const setUsers = useMessagingStore((state) => state.setUsers);
    const selectUser = useMessagingStore((state) => state.selectUser);

    // Initialisation des notifications Pusher Beams
    useEffect(() => {
        initializeBeams().catch((error) => {
            console.error(
                "Impossible d'initialiser les notifications :",
                error
            );
        });
    }, []);

    // Chargement de la liste des utilisateurs
    useEffect(() => {
        getUsers(
            (result: PublicUser[]) => {
                setUsers(result);
                setLoading(false);
            },
            (apiError: CustomError) => {
                setError(apiError.message);
                setLoading(false);

                if (apiError.httpStatus === 401) {
                    sessionStorage.clear();
                    navigate("/login", { replace: true });
                }
            }
        );
    }, [navigate, setUsers]);

    return (
        <div className="container py-5">
            <div className="d-flex justify-content-between align-items-center mb-4">
                <h1 className="h3 mb-0">Utilisateurs</h1>

                <button
                    type="button"
                    className="btn btn-outline-secondary"
                    onClick={() => {
                        sessionStorage.clear();
                        navigate("/login", { replace: true });
                    }}
                >
                    Déconnexion
                </button>
            </div>

            {loading && (
                <p className="text-secondary">
                    Chargement des utilisateurs...
                </p>
            )}

            {error && (
                <div className="alert alert-danger" role="alert">
                    {error}
                </div>
            )}

            {!loading && !error && users.length === 0 && (
                <p className="text-secondary">
                    Aucun utilisateur disponible.
                </p>
            )}

            {!loading && !error && users.length > 0 && (
                <div className="list-group shadow-sm">
                    {users.map((user) => (
                        <button
                            key={user.user_id}
                            type="button"
                            className="list-group-item list-group-item-action d-flex justify-content-between align-items-center py-3 text-start"
                            onClick={() => {
                                selectUser(user);
                                navigate(`/messages/user/${user.user_id}`);
                            }}
                        >
                            <div>
                                <div className="fw-semibold">
                                    {user.username}
                                </div>

                                <small className="text-secondary">
                                    Dernière connexion :{" "}
                                    {user.last_login || "Jamais"}
                                </small>
                            </div>

                            <span
                                className="text-primary"
                                aria-hidden="true"
                            >
                                →
                            </span>
                        </button>
                    ))}
                </div>
            )}
        </div>
    );
}

import { useCallback, useEffect, useRef, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { CustomError } from "../model/CustomError";
import { useMessagingStore } from "../store/messagingStore";
import { getMessages, sendMessage } from "./messagesApi";
import { getUsers, type PublicUser } from "./usersApi";

export function Conversation() {
    const { userId } = useParams();
    const navigate = useNavigate();

    const users = useMessagingStore((state) => state.users);
    const setUsers = useMessagingStore((state) => state.setUsers);
    const selectUser = useMessagingStore((state) => state.selectUser);
    const messages = useMessagingStore((state) => state.messages);
    const setMessages = useMessagingStore((state) => state.setMessages);
    const addMessage = useMessagingStore((state) => state.addMessage);

    const [targetUser, setTargetUser] = useState<PublicUser | null>(null);
    const [content, setContent] = useState("");
    const [loading, setLoading] = useState(true);
    const [sending, setSending] = useState(false);
    const [error, setError] = useState("");

    const bottomRef = useRef<HTMLDivElement>(null);
    const currentUserId = Number(sessionStorage.getItem("userId"));
    const targetId = Number(userId);

    useEffect(() => {
        if (!sessionStorage.getItem("token")) {
            navigate("/login", { replace: true });
            return;
        }

        if (!Number.isInteger(targetId) || targetId <= 0) {
            navigate("/users", { replace: true });
            return;
        }

        const existingUser = users.find(
            (user) => user.user_id === targetId
        );

        if (existingUser) {
            setTargetUser(existingUser);
            return;
        }

        getUsers(
            (result) => {
                setUsers(result);
                const found = result.find(
                    (user) => user.user_id === targetId
                );

                if (found) {
                    setTargetUser(found);
                } else {
                    setError("Cet utilisateur est introuvable.");
                }
            },
            (apiError: CustomError) => {
                setError(apiError.message);

                if (apiError.httpStatus === 401) {
                    sessionStorage.clear();
                    navigate("/login", { replace: true });
                }
            }
        );
    }, [navigate, setUsers, targetId, users]);

    const loadMessages = useCallback(async () => {
        try {
            const result = await getMessages(targetId);
            setMessages(result);
            setError("");
        } catch (apiError) {
            const message =
                apiError instanceof Error
                    ? apiError.message
                    : "Impossible de charger les messages.";

            setError(message);

            if (
                apiError instanceof CustomError &&
                apiError.httpStatus === 401
            ) {
                sessionStorage.clear();
                navigate("/login", { replace: true });
            }
        } finally {
            setLoading(false);
        }
    }, [navigate, setMessages, targetId]);

    useEffect(() => {
        if (!targetUser) return;

        selectUser(targetUser);
        setLoading(true);
        void loadMessages();

        const intervalId = window.setInterval(() => {
            void loadMessages();
        }, 5000);

        return () => window.clearInterval(intervalId);
    }, [loadMessages, selectUser, targetUser]);

    useEffect(() => {
        bottomRef.current?.scrollIntoView({ behavior: "smooth" });
    }, [messages]);

    async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
        event.preventDefault();

        const text = content.trim();

        if (!text || sending) return;

        setSending(true);
        setError("");

        try {
            const message = await sendMessage(targetId, text);
            addMessage(message);
            setContent("");
        } catch (apiError) {
            setError(
                apiError instanceof Error
                    ? apiError.message
                    : "Impossible d'envoyer le message."
            );
        } finally {
            setSending(false);
        }
    }

    return (
        <div className="container py-4" style={{ maxWidth: "850px" }}>
            <div className="card shadow-sm">
                <div className="card-header bg-white py-3">
                    <div className="d-flex align-items-center gap-3">
                        <button
                            className="btn btn-outline-secondary btn-sm"
                            onClick={() => navigate("/users")}
                        >
                            Retour
                        </button>

                        <div>
                            <h1 className="h5 mb-0">
                                {targetUser?.username || "Conversation"}
                            </h1>
                            <small className="text-secondary">
                                Messagerie privée
                            </small>
                        </div>
                    </div>
                </div>

                <div
                    className="card-body bg-light"
                    style={{ height: "55vh", minHeight: "300px", overflowY: "auto" }}
                >
                    {loading && (
                        <p className="text-secondary text-center">
                            Chargement des messages...
                        </p>
                    )}

                    {!loading && messages.length === 0 && !error && (
                        <p className="text-secondary text-center mt-4">
                            Aucun message. Envoyez le premier !
                        </p>
                    )}

                    {messages.map((message, index) => {
                        const isMine = message.senderId === currentUserId;

                        return (
                            <div
                                key={message.id || `${message.createdAt}-${index}`}
                                className={`d-flex mb-3 ${
                                    isMine
                                        ? "justify-content-end"
                                        : "justify-content-start"
                                }`}
                            >
                                <div
                                    className={`rounded-3 px-3 py-2 ${
                                        isMine
                                            ? "bg-primary text-white"
                                            : "bg-white border"
                                    }`}
                                    style={{ maxWidth: "80%", overflowWrap: "anywhere" }}
                                >
                                    <div className="small fw-semibold mb-1">
                                        {isMine ? "Vous" : message.senderUsername}
                                    </div>

                                    <div>{message.content}</div>

                                    <div
                                        className={`small mt-1 ${
                                            isMine
                                                ? "text-white-50"
                                                : "text-secondary"
                                        }`}
                                    >
                                        {new Date(message.createdAt).toLocaleString("fr-FR")}
                                    </div>
                                </div>
                            </div>
                        );
                    })}

import { AUTHENT_HEADER, BEARER } from "../model/common";
import { CustomError } from "../model/CustomError";

export interface PublicUser {
    user_id: number;
    username: string;
    last_login: string | null;
}

export function getUsers(
    onResult: (users: PublicUser[]) => void,
    onError: (error: CustomError) => void
) {
    const token = sessionStorage.getItem("token");

    if (!token) {
        const error = new CustomError("Vous devez vous connecter.");
        error.code = "UNAUTHORIZED";
        error.httpStatus = 401;
        onError(error);
        return;
    }

    fetch("/api/users", {
        method: "GET",
        headers: {
            [AUTHENT_HEADER]: BEARER + token,
        },
    })
        .then(async (response) => {
            if (!response.ok) {
                const data = await response.json().catch(() => null);
                const error = new CustomError(
                    data?.message || "Impossible de récupérer les utilisateurs."
                );
                error.code = data?.code;
                error.httpStatus = response.status;
                throw error;
            }

            return response.json() as Promise<PublicUser[]>;
        })
        .then(onResult)
        .catch((error: unknown) => {
            if (error instanceof CustomError) {
                onError(error);
            } else {
                onError(new CustomError("Erreur de communication avec le serveur."));
            }
        });
}

import { AUTHENT_HEADER, BEARER } from "../model/common";
